-- Import "Ferramentas" category and catalog items from PDF
-- Idempotent: safe to run multiple times

-- Step 1: Ensure user lptamborini@hotmail.com exists
DO $$
DECLARE
  new_user_id uuid;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM auth.users WHERE email = 'lptamborini@hotmail.com') THEN
    new_user_id := gen_random_uuid();
    INSERT INTO auth.users (
      id, instance_id, email, encrypted_password, email_confirmed_at,
      created_at, updated_at, raw_app_meta_data, raw_user_meta_data,
      is_super_admin, role, aud,
      confirmation_token, recovery_token, email_change_token_new,
      email_change, email_change_token_current,
      phone, phone_change, phone_change_token, reauthentication_token
    ) VALUES (
      new_user_id,
      '00000000-0000-0000-0000-000000000000',
      'lptamborini@hotmail.com',
      crypt('Skip@Pass', gen_salt('bf')),
      NOW(), NOW(), NOW(),
      '{"provider": "email", "providers": ["email"]}',
      '{"name": "Master"}',
      false, 'authenticated', 'authenticated',
      '', '', '', '', '', NULL, '', '', ''
    );
    INSERT INTO public.profiles (id, email, name, role)
    VALUES (new_user_id, 'lptamborini@hotmail.com', 'Master', 'Master')
    ON CONFLICT (id) DO NOTHING;
  ELSE
    UPDATE public.profiles SET role = 'Master'
    WHERE email = 'lptamborini@hotmail.com';
  END IF;
END $$;

-- Step 2: Ensure profile has client_id set
DO $$
DECLARE
  v_client_id uuid;
BEGIN
  SELECT id INTO v_client_id FROM public.clients ORDER BY created_at LIMIT 1;
  IF v_client_id IS NOT NULL THEN
    UPDATE public.profiles SET client_id = v_client_id
    WHERE email = 'lptamborini@hotmail.com' AND client_id IS NULL;
  END IF;
END $$;

-- Step 3: Add Ferramentas category and import products
DO $$
DECLARE
  v_client_id uuid;
BEGIN
  SELECT COALESCE(p.client_id, (SELECT id FROM public.clients ORDER BY created_at LIMIT 1))
  INTO v_client_id
  FROM public.profiles p
  WHERE p.email = 'lptamborini@hotmail.com';

  IF v_client_id IS NULL THEN
    v_client_id := (SELECT id FROM public.clients ORDER BY created_at LIMIT 1);
  END IF;

  IF v_client_id IS NULL THEN
    RAISE NOTICE 'No client found, skipping Ferramentas import';
    RETURN;
